import {fieldSceneHTML} from './field3d.mjs';
import {rotationPhotos,cropGallery} from './photos.mjs';
import {crops,rotations,rotationName,months,MODEL_VERSION,FAO,CALENDAR_SOURCE,historicalRange} from './engine.mjs';
export const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const num=(n,d=0)=>Number(n).toLocaleString('en',{maximumFractionDigits:d,minimumFractionDigits:d});
export const icon=(name)=>`<svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${({home:'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',dashboard:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="11" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="18" width="7" height="3" rx="1"/>',fields:'<path d="m3 7 6-3 6 3 6-3v14l-6 3-6-3-6 3Z"/><path d="M9 4v14M15 7v14"/>',planner:'<rect x="4" y="5" width="16" height="16" rx="2"/><path d="M8 3v4M16 3v4M4 10h16m-12 5 3 3 5-5"/>',compare:'<path d="M6 3v18M18 3v18M3 8h6M15 16h6"/><circle cx="6" cy="8" r="2" fill="currentColor"/><circle cx="18" cy="16" r="2" fill="currentColor"/>',evidence:'<path d="M4 4h7a3 3 0 0 1 1 1 3 3 0 0 1 1-1h7v16h-7a3 3 0 0 0-1 1 3 3 0 0 0-1-1H4Z"/><path d="M12 5v16M7 8h2M15 8h2M7 12h2M15 12h2"/>',plans:'<path d="M6 3h12v19l-6-4-6 4Z"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',water:'<path d="M12 3S5 11 5 15a7 7 0 0 0 14 0c0-4-7-12-7-12Z"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1 1M18 18l1 1M5 19l1-1M18 6l1-1"/>',leaf:'<path d="M4 20C2 8 8 4 21 3c-1 13-5 19-17 17ZM4 20 16 8"/>',plus:'<path d="M12 5v14M5 12h14"/>'})[name]||'<circle cx="12" cy="12" r="8"/>'}</svg>`;
export const button=(action,label,cls='secondary',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
export function heading(kicker,title,description='',action=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1>${description?`<p>${description}</p>`:''}</div>${action}</div>`}
export function select(name,label,items,value){return `<label class="form-label">${label}<select name="${name}" data-setting="${name}">${items.map(([v,l])=>`<option value="${v}" ${String(v)===String(value)?'selected':''}>${l}</option>`).join('')}</select></label>`}
export const yearSelect=s=>select('year','Historical crop year',[2021,2022,2023,2024].map(y=>[y,`${y}–${String(y+1).slice(2)}`]),s.year);
export function notice(c){if(!c.field)return `<div class="empty-state"><div class="empty-icon">${icon('fields')}</div><h2>A new season starts with a field.</h2><p>Add a field or open the demo to begin exploring.</p>${button('new-field','Add your first field','primary')}${button('demo','Open Pune demo','secondary')}</div>`;if(c.loading)return '<div class="loading-state"><span class="spinner"></span><h2>Bringing the weather into focus.</h2><p>Loading NASA history for this field. Scores will appear when the record is ready.</p></div>';if(c.error)return `<div class="empty-state error"><h2>We cannot evaluate this window yet.</h2><p>${esc(c.error)}</p>${button('reload','Retry data request')}${button('reset-settings','Restore supported calendar')}${button('demo','Open saved Pune demo')}</div>`;return ''}
export function dataBadge(c){return `<span class="data-badge"><span class="dot"></span> NASA POWER · ${c.field?.demo?'Saved demo record':'Historical record'}</span>`}
export function stat(label,value,unit,sub,kind='leaf'){return `<article class="stat-card"><div class="stat-label">${label}<span>${icon(kind)}</span></div><div class="stat-number">${value}<small>${unit}</small></div><p>${sub}</p></article>`}
export function chart(weather,kind='rain'){
 const rows=weather.flatMap(w=>w.monthly),values=rows.map(r=>r[kind]),max=Math.max(...values,kind==='rain'?100:40)*1.12,width=680,height=214,xStep=600/rows.length;
 const grid=[0,.25,.5,.75,1].map(f=>`<line x1="45" y1="${180-f*150}" x2="655" y2="${180-f*150}" stroke="#e8eade"/><text x="35" y="${184-f*150}" text-anchor="end" fill="#849079" font-size="10">${Math.round(max*f)}</text>`).join('');
 const bars=rows.map((r,i)=>`<rect x="${50+i*xStep}" y="${180-r[kind]/max*150}" width="${xStep*.58}" height="${r[kind]/max*150}" rx="3" fill="${kind==='rain'?'#8da77c':'#c7966e'}"/><text x="${50+i*xStep+xStep*.29}" y="202" text-anchor="middle" font-size="10" fill="#77836e">${r.label.split(' ')[0]}</text>`).join('');
 return `<div class="chart-wrap"><svg viewBox="0 0 ${width} ${height}" role="img" aria-label="${kind==='rain'?'Monthly precipitation in millimeters':'Monthly mean temperature in degrees Celsius'}"><title>Observed monthly ${kind==='rain'?'rainfall':'mean temperature'} for both selected growing windows</title>${grid}${bars}</svg></div><details class="chart-data"><summary>View ${kind==='rain'?'rainfall':'temperature'} data table</summary><div class="table-scroll"><table><thead><tr><th>Month</th><th>${kind==='rain'?'Rainfall (mm)':'Mean temperature (°C)'}</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.label}</td><td>${num(r[kind],1)}</td></tr>`).join('')}</tbody></table></div></details>`;
}
export function fieldSketch(field){return `<div class="field-sketch"><svg viewBox="0 0 400 140" role="img" aria-label="Illustrative field sketch, not a map"><defs><pattern id="sketch-${esc(field.id)}" width="17" height="17" patternUnits="userSpaceOnUse" patternTransform="rotate(-26)"><path d="M0 0V17" stroke="#bbcaa0" stroke-width="7"/></pattern></defs><path d="m30 82 125-62 104 22 108 60-153 26Z" fill="#ced8b6"/><path d="m30 82 125-62 104 22 108 60-153 26Z" fill="url(#sketch-${esc(field.id)})"/><path d="m155 20 59 108M55 70l276 33" stroke="#f7f3df" stroke-width="7"/><circle cx="213" cy="70" r="9" fill="#204d3c" stroke="#fff" stroke-width="3"/></svg><span>FIELD SKETCH · ILLUSTRATIVE</span></div>`}
function home(){return `<section class="home-hero"><div><div class="eyebrow"><span class="dot"></span> NASA DATA. YOUR FIELD. YOUR NEXT MOVE.</div><h1>Your next season,<br><em>considered.</em></h1><p>Understand the weather. Explore your options.<br>Build a rotation around what matters to your field.</p><div class="actions"><a class="primary" href="#fields">Start with your field ${icon('arrow')}</a>${button('demo','Explore the demo ↗','text-button')}</div><div class="hero-proof"><span class="tiny-icon">${icon('evidence')}</span><span>Real observations.<br><b>Reasoning you can inspect.</b></span></div></div><div class="hero-art hero-world">${fieldSceneHTML()}</div></section><section class="journey-strip"><div><span>01</span><b>Know your field</b><p>Soil, water & crop history</p></div><div><span>02</span><b>Read the conditions</b><p>Four years of NASA history</p></div><div><span>03</span><b>Explore the trade-offs</b><p>Compare both growing seasons</p></div><div><span>04</span><b>Keep your reasoning</b><p>Save a traceable plan</p></div></section>${cropGallery()}<section class="home-bottom"><div><div class="eyebrow">FROM OBSERVATION TO EXPLORATION</div><h2>A useful answer starts<br>with a better question.</h2><p>“What could I plant if the next season is hotter, or I have less irrigation?”</p><a class="inline-link" href="#compare">Explore a scenario ${icon('arrow')}</a></div><article class="feature-panel"><div class="feature-icon">${icon('planner')}</div><h3>More than a crop score.</h3><p>Explore two-season rotations, see why candidates are excluded, and compare the effect of changing your assumptions.</p><a href="#planner">Open the rotation planner ↗</a></article><article class="feature-panel"><div class="feature-icon">${icon('evidence')}</div><h3>Every number has a story.</h3><p>Separate NASA weather observations from your field inputs and the model's assumptions. Follow the evidence all the way back.</p><a href="#evidence">Inspect the evidence ↗</a></article></section><div class="honesty-banner">${icon('leaf')}<span><b>Built to support better questions.</b> An independent hackathon exploration tool. Crop parameters still need local agronomic validation.</span></div>`}
function dashboard(c){const n=notice(c);if(n)return heading('YOUR FIELD, IN PERSPECTIVE','A little context. A clearer next step.')+n;const {result:r,field:f,settings:s}=c,best=r.ranked.find(x=>x.eligible),rain=r.weather.reduce((sum,w)=>sum+w.rain,0),days=r.weather.reduce((sum,w)=>sum+w.days,0),avg=r.weather.reduce((sum,w)=>sum+w.avg*w.days,0)/days;return heading('FIELD OVERVIEW','A little context. A clearer next step.',`${esc(f.name)} · ${f.lat.toFixed(2)}°, ${f.lon.toFixed(2)}° · ${num(f.area,1)} hectares`,yearSelect(s))+`<div class="context-line">${dataBadge(c)}<span>Observed history · ${s.year}–${s.year+1} · Two four-month windows</span></div><div class="stats-grid">${stat('Rain across both windows',num(rain),'mm','Historical precipitation · not a forecast','water')}${stat('Mean temperature',num(avg,1),'°C',`${days} complete observed days`,'sun')}${stat('Candidates passing demo rules',r.ranked.filter(x=>x.eligible).length,'/ 5','Calendar + soil exclusions applied','leaf')}${stat('Your saved plans',c.state.plans.filter(p=>p.field.id===f.id).length,'plans','Stored on this device','plans')}</div><div class="dashboard-grid"><section class="panel history-panel"><div class="panel-head"><div><div class="eyebrow">WEATHER HISTORY</div><h2>When the rain arrived.</h2></div><span class="unit-tag">RAINFALL · MM</span></div>${chart(r.weather)}<div class="chart-caption">Season 1: ${r.weather[0].window.label}<span>Season 2: ${r.weather[1].window.label}</span></div></section><section class="next-card"><span class="eyebrow">YOUR NEXT EXPLORATION</span><h2>${best?rotationName(best):'Revisit your planting windows.'}</h2><p>${best?'The highest score under your current assumptions. Explore the reasons and compare it with your current baseline.':'No candidate passes these calendar and soil rules. Adjust your windows to explore other options.'}</p>${best?`<div class="next-score">${best.score}<span>/ 100 · model score</span></div>`:''}<a class="light-button" href="#planner">See the rotation shortlist ${icon('arrow')}</a><small>Active scenario · season 1: ${s.rainChange}% rain, +${s.heatChange}°C, ${s.firstIrrigation} mm irrigation. Season 2: ${s.secondRainChange}% rain, +${s.secondHeatChange}°C, ${s.secondIrrigation} mm irrigation.<br>Illustrative model · not validated advice</small></section><section class="panel"><div class="panel-head"><div><div class="eyebrow">TEMPERATURE HISTORY</div><h2>The seasonal picture.</h2></div><span class="unit-tag">MEAN · °C</span></div>${chart(r.weather,'avg')}</section><section class="panel field-summary"><div class="panel-head"><h2>Your field profile</h2>${button('edit-field','Edit','text-button',`data-id="${esc(f.id)}"`)}</div>${fieldSceneHTML(true)}<dl><div><dt>Soil texture</dt><dd>${esc(f.soil)}</dd></div><div><dt>Previous crop</dt><dd>${crops[f.previous].name}</dd></div><div><dt>Default irrigation</dt><dd>${f.irrigation} mm / season</dd></div></dl><p class="muted small">${f.demo?'Illustrative field profile at a real reference location.':'Manual field inputs. NASA data describe the regional grid.'}</p></section></div><div class="honesty-banner">${icon('evidence')}<span>NASA POWER is regional gridded weather. Your field area does not change its spatial resolution. <a href="#evidence">See sources & assumptions ↗</a></span></div>`}
function fields(c){return heading('YOUR LAND, YOUR CONTEXT','Every field has its own story.','Create field profiles to keep soil, irrigation and crop history together.',button('new-field',`${icon('plus')} Add a field`,'primary'))+`<div class="storage-note">${icon('plans')} Field profiles and plans are stored in this browser. Export important plans to keep a backup.</div><div class="field-grid">${c.state.fields.map(f=>`<article class="panel field-card">${fieldSketch(f)}<div class="field-title"><h2>${esc(f.name)}</h2>${f.id===c.state.activeFieldId?'<span class="tag">ACTIVE</span>':''}</div><p class="muted">${f.lat.toFixed(2)}°, ${f.lon.toFixed(2)}° ${f.demo?'· Demo profile':''}</p><div class="field-facts"><span><b>${num(f.area,1)} ha</b>Field area</span><span><b>${f.soil}</b>Soil texture</span><span><b>${crops[f.previous].name}</b>Previous crop</span></div><div class="card-actions">${button('select-field','Open field →','secondary',`data-id="${esc(f.id)}"`)}${button('edit-field','Edit','text-button',`data-id="${esc(f.id)}"`)}${button('delete-field','Remove','text-button danger',`data-id="${esc(f.id)}"`)}</div></article>`).join('')}<button class="add-field-card" data-action="new-field"><span>+</span><h3>A different field?</h3><p>Add its own soil and water context.</p></button></div><div class="honesty-banner">${icon('fields')}<span>Selecting a custom field loads NASA weather for its coordinates. Field sketches are illustrations; no field boundaries or satellite map are inferred.</span></div>`}
function planner(c){return heading('THE ROTATION PLANNER','What could your next rotation look like?','Set your windows and priorities. Explore candidates that pass the demo rules.',`<a href="#compare" class="secondary">Compare rotations ${icon('arrow')}</a>`)+(c.field?`<div class="planning-layout"><aside class="panel planner-controls"><div class="eyebrow">01 / YOUR PLANNING INPUTS</div><h3>Make the context yours.</h3>${yearSelect(c.settings)}<div class="form-divider">GROWING WINDOWS · FOUR MONTHS EACH</div>${select('firstMonth','Season 1 begins',[5,6,7,8,9].map(m=>[m,months[m-1]]),c.settings.firstMonth)}${select('secondMonth','Season 2 begins',[9,10,11,12].map(m=>[m,months[m-1]]),c.settings.secondMonth)}<p class="small muted">Fixed four-month screening windows. Exact crop durations and planting dates require regional validation.</p><div class="form-divider">WATER & PRIORITIES</div>${slider('firstIrrigation','Season 1 irrigation',c.settings.firstIrrigation,0,1000,25,'mm')}${slider('secondIrrigation','Season 2 irrigation',c.settings.secondIrrigation,0,1000,25,'mm')}${select('priority','Prioritize',[['balanced','A balanced rotation'],['water','Water availability'],['soil','Soil & crop diversity']],c.settings.priority)}<div class="input-summary">${icon('leaf')} ${esc(c.field.soil)} soil · previous ${crops[c.field.previous].name}<a href="#fields">Edit field profile ↗</a></div>${button('reset-settings','Reset planning inputs','secondary full')}</aside><div id="planner-results">${plannerResults(c)}</div></div>`:notice(c))}
export function plannerResults(c){const n=notice(c);if(n)return n;const r=c.result,best=r.ranked.find(x=>x.eligible);return `<div class="result-toolbar"><span class="eyebrow">02 / YOUR ROTATION SHORTLIST</span>${button('save-plan',`${icon('plans')} Save this plan`,'primary small-button',best?'':'disabled')}</div><div class="mini-notice">${dataBadge(c)}<span>Both seasons screened · calendar assumptions apply</span></div>${r.ranked.map((x,i)=>rotationCard(x,i,c)).join('')}<div class="model-footnote"><b>Scores help compare assumptions.</b> They are not probabilities, yield predictions or locally validated advice. Scenario changes are retained when navigating between Planner and Compare. <a href="#evidence">Inspect the model ↗</a></div>`}
function rotationCard(r,i,c){return `<article class="rotation-card ${!r.eligible?'excluded':''}">${rotationPhotos(r.pair)}<div class="rotation-header"><div><span class="eyebrow">${r.eligible?`${String(i+1).padStart(2,'0')} / ${r.label.toUpperCase()}`:'EXCLUDED BY DEMO RULES'}</span><h2>${rotationName(r)}</h2></div><div class="rotation-score">${r.eligible?`${r.score}<small>/100</small>`:'—'}</div></div>${r.eligible?`<div class="calendar-tags"><span>01 · ${r.seasons[0].window}</span><span>02 · ${r.seasons[1].window}</span></div><div class="component-grid">${[['Water fit',r.water],['Soil & diversity',r.soilScore],['Heat fit',r.heat]].map(([label,n])=>`<div><span>${label}<b>${num(n)}</b></span><div class="progress-track"><i style="width:${n}%"></i></div></div>`).join('')}</div><details class="reason-details"><summary>Why this score? Inspect both seasons</summary>${seasonTable(r)}<p class="small muted">Usable water = rainfall × scenario adjustment × 65% + irrigation. Soil/diversity score: ${r.soilScore}/100. Heat thresholds, soil preferences and the 65% factor are demo assumptions.</p></details><div class="rotation-bottom"><span>Modeled unmet water need <b>${num(r.gap)} mm</b></span><label class="check-label"><input type="checkbox" data-compare="${r.id}" ${c.state.compare.includes(r.id)?'checked':''}> Compare</label></div>`:`<ul class="exclusion-list">${r.excluded.map(e=>`<li>${esc(e)}</li>`).join('')}</ul>`}</article>`}
export function seasonTable(r){return `<div class="table-scroll"><table><thead><tr><th>Season / crop</th><th>Usable water</th><th>Demand*</th><th>Gap*</th><th>Hot days*</th></tr></thead><tbody>${r.seasons.map((s,i)=>`<tr><td>${i+1} · ${s.name}</td><td>${num(s.supply)} mm</td><td>${s.demand} mm</td><td>${num(s.gap)} mm</td><td>${s.hotDays}/${s.days} &gt; ${s.threshold}°C</td></tr>`).join('')}</tbody></table></div>`}
export function slider(name,label,value,min,max,step,unit){return `<label class="slider-label">${label}<output data-output="${name}">${value}${unit==='°C'?'°C':unit==='%'?'%':` ${unit}`}</output><input aria-label="${label} · ${name.startsWith('second')?'season 2':'season 1'}" type="range" data-setting="${name}" name="${name}" min="${min}" max="${max}" step="${step}" value="${value}"></label>`}
function compare(c){return heading('THE SCENARIO LAB','A different season. A different decision?','Compare options against observed weather, then change the assumptions.',button('save-plan',`${icon('plans')} Save scenario`,'primary',c.result?'':'disabled'))+(c.field?`<div class="scenario-presets"><span>TRY A SCENARIO</span>${button('preset','Observed baseline','preset', 'data-preset="baseline"')}${button('preset','Hotter + drier','preset','data-preset="hotdry"')}${button('preset','Less irrigation','preset','data-preset="water"')}</div><div class="planning-layout"><aside class="panel scenario-controls"><div class="eyebrow">CHANGE THE ASSUMPTIONS</div><h3>Explore the “what if”.</h3><p class="small muted">Adjustments apply to history. They are not forecasts.</p>${yearSelect(c.settings)}<div class="form-divider">SEASON 1</div>${slider('rainChange','Rainfall change',c.settings.rainChange,-60,30,5,'%')}${slider('heatChange','Temperature increase',c.settings.heatChange,0,5,.5,'°C')}${slider('firstIrrigation','Irrigation available',c.settings.firstIrrigation,0,1000,25,'mm')}<div class="form-divider">SEASON 2</div>${slider('secondRainChange','Rainfall change',c.settings.secondRainChange,-60,30,5,'%')}${slider('secondHeatChange','Temperature increase',c.settings.secondHeatChange,0,5,.5,'°C')}${slider('secondIrrigation','Irrigation available',c.settings.secondIrrigation,0,1000,25,'mm')}<a class="inline-link small" href="#planner">Change season windows & priorities ↗</a></aside><div id="compare-results">${compareResults(c)}</div></div>`:notice(c))}
export function compareResults(c){const n=notice(c);if(n)return n;const selected=c.result.ranked.filter(x=>c.state.compare.includes(x.id)),base=c.baseline;return `<div class="panel comparison-picker"><div class="panel-head"><h3>Choose up to three rotations</h3><span class="muted small">${selected.length} / 3 selected</span></div><div class="choice-chips">${rotations.map(r=>`<label><input type="checkbox" data-compare="${r.id}" ${c.state.compare.includes(r.id)?'checked':''}><span>${rotationName(r)}</span></label>`).join('')}</div></div>${selected.length?`<div class="compare-columns">${selected.map(r=>{const b=base.ranked.find(x=>x.id===r.id);return `<article class="panel compare-card">${rotationPhotos(r.pair)}<div class="eyebrow">${r.label.toUpperCase()}</div><h2>${rotationName(r)}</h2>${r.eligible?`<div class="comparison-score"><strong>${r.score}</strong><span>/100<br>scenario score</span></div><div class="baseline-line">Observed baseline <b>${b.score}</b><span class="delta">${r.score-b.score>0?'+':''}${r.score-b.score} pts</span></div><dl class="comparison-facts"><div><dt>Water fit</dt><dd>${num(r.water)} / 100</dd></div><div><dt>Heat fit</dt><dd>${num(r.heat)} / 100</dd></div><div><dt>Soil & diversity</dt><dd>${r.soilScore} / 100</dd></div><div><dt>Modeled water gap</dt><dd>${num(r.gap)} mm</dd></div><div><dt>Gap across ${num(c.field.area,1)} ha</dt><dd>${num(r.volume)} m³</dd></div></dl><p class="small muted">Total gap is a modeled unmet crop-water need, not a withdrawal or irrigation prescription.</p><div class="calendar-stack">${r.seasons.map((s,i)=>`<div><span>SEASON ${i+1}</span><b>${s.name}</b><small>${s.window}</small></div>`).join('')}</div>`:`<div class="excluded-label">Excluded by demo rules</div><ul class="exclusion-list">${r.excluded.map(e=>`<li>${esc(e)}</li>`).join('')}</ul>`}</article>`}).join('')}</div><section class="panel range-panel"><div class="panel-head"><div><div class="eyebrow">HISTORICAL SENSITIVITY</div><h2>Does the result hold across years?</h2></div></div><p class="muted small">Same inputs and scenario applied to each year's observed weather. These are model score ranges, not confidence intervals.</p>${historyTable(c,selected)}</section>`:'<div class="empty-state"><h2>Pick a rotation to start comparing.</h2><p>Select up to three options above.</p></div>'}<div class="honesty-banner">${icon('evidence')}<span>The observed baseline uses the field's default irrigation in each season and no rainfall or heat adjustment. Your calendar and scoring priorities stay the same.</span></div>`}
function historyTable(c,selected){const history=historicalRange(c.record,c.field,c.settings);return `<div class="table-scroll"><table><thead><tr><th>Rotation</th>${history.map(x=>`<th>${x.year}–${String(x.year+1).slice(2)}</th>`).join('')}<th>Score range</th></tr></thead><tbody>${selected.map(r=>{const scores=history.map(h=>h.result?.ranked.find(x=>x.id===r.id)?.score);const valid=scores.filter(x=>x!==null&&x!==undefined);return `<tr><td>${rotationName(r)}</td>${scores.map((x,i)=>`<td>${x??'Unavailable'}${history[i].error?`<span class="small muted"> · incomplete</span>`:''}</td>`).join('')}<td>${valid.length?`${Math.min(...valid)}–${Math.max(...valid)}`:'—'}</td></tr>`}).join('')}</tbody></table></div>`}
function evidence(c){return heading('THE EVIDENCE LIBRARY','Follow every result back to its roots.','Observations, field inputs and assumptions — visible in one place.')+`<div class="evidence-intro"><span class="evidence-symbol">${icon('evidence')}</span><div><h2>Clear sources. Honest limits.</h2><p>NASA observes the weather. You describe the field. An explicit model compares the options. No trained AI or yield forecasting is used.</p></div><span class="version-tag">MODEL ${MODEL_VERSION}</span></div><div class="evidence-grid"><section class="panel"><div class="eyebrow">01 / NASA OBSERVATIONS</div><h2>Weather history</h2>${c.record?`<dl class="metadata"><div><dt>Product</dt><dd>NASA POWER Daily</dd></div><div><dt>Parameters</dt><dd>T2M · T2M_MAX · PRECTOTCORR</dd></div><div><dt>Source products</dt><dd>${esc(c.record.data.header?.sources?.join(', ')||'See raw response')}</dd></div><div><dt>Requested location</dt><dd>${esc(c.record.requested_location?.lat)}°, ${esc(c.record.requested_location?.lon)}°</dd></div><div><dt>Native returned geometry</dt><dd>${esc(JSON.stringify(c.record.data.geometry?.coordinates||[]))}</dd></div><div><dt>Period</dt><dd>June 2021 – May 2025</dd></div><div><dt>Retrieved</dt><dd>${esc(c.record.retrieved_at?.slice(0,19).replace('T',' '))} UTC</dd></div><div><dt>Selected-window coverage</dt><dd>${c.result?'100% of days in both windows':'Unavailable; evaluation is blocked'}</dd></div></dl><div class="actions"><a class="secondary" target="_blank" rel="noopener" href="${esc(c.record.request_url)}">Exact NASA request ↗</a>${button('export-dataset','Download source record','text-button')}</div>`:`<p class="muted">${c.loading?'Loading the current field record…':'Select a field and load its weather history to see record metadata.'}</p>`}<p class="small muted">Regional gridded meteorology, not field sensors. A returned point coordinate does not imply field-level spatial resolution. Source products retain their native spatial resolution.</p><a class="inline-link" target="_blank" rel="noopener" href="https://power.larc.nasa.gov/docs/services/api/temporal/daily/">NASA POWER documentation ↗</a></section><section class="panel"><div class="eyebrow">02 / THE MODEL</div><h2>Reasoning in plain sight</h2><ol class="model-list"><li><b>Filter calendar & soil rules.</b> Check assumed planting months, overlapping four-month windows and the demo's sandy-soil rice exclusion.</li><li><b>Screen each season independently.</b> Water fit = min(100, (rain × adjustment × 0.65 + irrigation) ÷ assumed demand × 100).</li><li><b>Count hot days.</b> Heat fit is the share of days not exceeding the crop's illustrative maximum-temperature threshold after adjustment.</li><li><b>Combine the evidence.</b> Average both seasons' water and heat scores, then weight them alongside the soil/diversity heuristic.</li></ol><div class="formula-block">Balanced: water 35% · soil 30% · heat 35%<br>Water priority: 60% · 20% · 20%<br>Soil priority: 20% · 60% · 20%</div><details><summary>Inspect the soil & diversity formula</summary><p class="small muted">Start at 25. Add 20 for season 1 soil match, 15 for season 2 match, 25 for a second-season pulse and 15 for different crop families. Subtract 15 when the previous and first crops share a family. Clamp to 0–100. This is a heuristic, not measured soil improvement. Score ties favor lower assumed combined water demand, then rotation identifier.</p></details></section></div><section class="panel crop-reference"><div class="panel-head"><div><div class="eyebrow">03 / CROP PARAMETERS</div><h2>Published context. Visible assumptions.</h2></div><span class="tag amber">LOCAL VALIDATION PENDING</span></div><p class="muted">Cereal demand values use midpoints of FAO's broad ranges. Pulse demand, all heat thresholds, exact calendar windows and soil preferences are illustrative. Rice demand here excludes additional paddy-system losses.</p><div class="table-scroll"><table><thead><tr><th>Crop</th><th>Demand / range (mm)</th><th>Heat threshold*</th><th>Demo start months*</th><th>Soil preference*</th><th>Water source</th></tr></thead><tbody>${Object.values(crops).map(x=>`<tr><td>${x.name}</td><td>${x.water}${x.waterRange?` / ${x.waterRange.join('–')}`:' / illustrative'}</td><td>${x.heat}°C</td><td>${x.months.map(m=>months[m-1]).join(', ')}</td><td>${x.soils.join(', ')}</td><td>${x.source?`<a href="${x.source}" target="_blank" rel="noopener">FAO range ↗</a>`:'Demo assumption'}</td></tr>`).join('')}</tbody></table></div><p class="small muted">*Not locally validated. General Indian Kharif/Rabi context: <a href="${CALENDAR_SOURCE}" target="_blank" rel="noopener">Indian Economic Service ↗</a>. Fixed four-month windows are screening periods, not precise crop-duration recommendations.</p></section><div class="evidence-grid"><section class="panel"><div class="eyebrow">04 / YOUR INPUTS</div><h2>A field is more than coordinates.</h2><p class="muted">Soil texture, area, previous crop and irrigation come from your profile. These are manual inputs; the site does not infer soil health or field boundaries from satellite imagery.</p><a href="#fields" class="inline-link">Review field profiles ↗</a></section><section class="panel"><div class="eyebrow">05 / WHAT IS NOT MODELED</div><h2>The limits matter.</h2><p class="muted">No yield, profit, soil carbon, planting-date optimization, root-zone water balance, carry-over soil moisture, pest pressure, salinity or crop-stage stress model. Four historical years do not establish a long-term climate trend. No live SMAP or IMERG layer is connected.</p></section></div>`}
function plans(c){return heading('YOUR SAVED PLANS','Keep the reasoning, not just the result.','Immutable snapshots of field inputs, NASA records and model results.',button('import-plan','↑ Import plan','secondary'))+`<div class="storage-note">${icon('plans')} Saved on this device. Export JSON to keep a portable backup. Imported files are validated and their scores recalculated.</div>${c.state.plans.length?`<div class="saved-grid">${c.state.plans.slice().reverse().map(p=>{const best=p.result.ranked.find(r=>r.eligible);return `<article class="panel saved-card"><div class="eyebrow">${p.settings.year}–${p.settings.year+1} · MODEL ${esc(p.modelVersion)}</div><h2>${esc(p.name)}</h2><p class="muted">${esc(p.field.name)} · ${num(p.field.area,1)} ha</p><div class="saved-rotation">${best?rotationName(best):'No eligible candidate'}<span>${best?best.score:'—'}</span></div><p class="small muted">Saved ${new Date(p.createdAt).toLocaleDateString('en-GB',{timeZone:'Asia/Kolkata'})} · ${p.settings.rainChange}% first-season rainfall adjustment</p><label class="check-label snapshot-choice"><input type="checkbox" data-snapshot="${esc(p.id)}" ${(c.state.comparePlanIds||[]).includes(p.id)?'checked':String()}> Compare this snapshot</label><div class="card-actions"><a class="secondary" href="#plan/${encodeURIComponent(p.id)}">Review plan →</a>${button('export-plan','Export','text-button',`data-id="${esc(p.id)}"`)}${button('delete-plan','Remove','text-button danger',`data-id="${esc(p.id)}"`)}</div></article>`}).join('')}</div>`:`<div class="empty-state"><div class="empty-icon">${icon('plans')}</div><h2>Your first plan is still ahead.</h2><p>Explore a rotation, adjust the assumptions and save a snapshot here.</p><a class="primary" href="#planner">Build a rotation plan ${icon('arrow')}</a></div>`}`}
function report(c){const p=c.plan;if(!p)return heading('SAVED PLAN','This plan is not on this device.')+'<a class="primary" href="#plans">Return to saved plans</a>';return heading('SAVED PLAN / IMMUTABLE SNAPSHOT',esc(p.name),`${esc(p.field.name)} · ${num(p.field.area,1)} ha · model ${esc(p.modelVersion)}`,`<div class="actions">${button('print-plan','Print / Save PDF','secondary')}${button('export-plan','Export JSON','primary',`data-id="${esc(p.id)}"`)}</div>`)+`<div class="report-content"><div class="report-banner"><b>${p.settings.year}–${p.settings.year+1} historical replay</b><span>Saved ${esc(p.createdAt)} · Results use this snapshot, not your current field settings.</span></div><section class="panel"><h2>Field & scenario</h2><dl class="metadata"><div><dt>Coordinates / soil</dt><dd>${p.field.lat}°, ${p.field.lon}° / ${p.field.soil}</dd></div><div><dt>Previous crop / priority</dt><dd>${crops[p.field.previous].name} / ${p.settings.priority}</dd></div><div><dt>Season 1 adjustments</dt><dd>${p.settings.rainChange}% rain · +${p.settings.heatChange}°C · ${p.settings.firstIrrigation} mm irrigation</dd></div><div><dt>Season 2 adjustments</dt><dd>${p.settings.secondRainChange}% rain · +${p.settings.secondHeatChange}°C · ${p.settings.secondIrrigation} mm irrigation</dd></div><div><dt>NASA request</dt><dd><a href="${esc(p.dataset.request_url)}" target="_blank" rel="noopener">Exact source request ↗</a></dd></div></dl></section>${p.result.ranked.map(r=>`<section class="panel report-rotation"><div class="panel-head"><h2>${rotationName(r)}</h2><b>${r.eligible?`${r.score} / 100`:'Excluded'}</b></div>${r.eligible?seasonTable(r):`<p>${r.excluded.map(esc).join(' ')}</p>`}</section>`).join('')}<div class="honesty-banner"><span><b>Exploration model ${MODEL_VERSION}.</b> FAO-context cereal demands; illustrative pulse demands, thresholds, calendar and soil rules. No locally validated recommendation, forecast, measured savings or yield prediction. Four-month windows screen both seasons. Water fit uses a fixed 65% usable-rain assumption. See the Evidence Library for formulas and source links.</span></div></div>`}
export function fieldForm(field){const f=field||{name:'',lat:18.52,lon:73.86,area:1,soil:'loam',previous:'rice',irrigation:200};return `<form id="field-form" data-id="${esc(field?.id||'')}"><div class="dialog-heading"><div><div class="eyebrow">YOUR FIELD PROFILE</div><h2>${field?'Edit your field':'A little ground truth.'}</h2></div><button type="button" data-action="close-dialog" class="icon-button" aria-label="Close dialog">×</button></div><p class="muted">Manual field inputs give weather history the right context.</p><label class="form-label">Field name<input name="name" required maxlength="80" value="${esc(f.name)}" placeholder="e.g. North field"></label><div class="form-two"><label class="form-label">Latitude<input name="lat" type="number" min="-90" max="90" step="any" required value="${f.lat}"></label><label class="form-label">Longitude<input name="lon" type="number" min="-180" max="180" step="any" required value="${f.lon}"></label></div><div class="form-two"><label class="form-label">Area (hectares)<input name="area" type="number" min="0.001" max="100000" step="any" required value="${f.area}"></label><label class="form-label">Soil texture<select name="soil">${['loam','clay','sandy'].map(x=>`<option ${x===f.soil?'selected':''}>${x}</option>`).join('')}</select></label></div><div class="form-two"><label class="form-label">Previous crop<select name="previous">${Object.entries(crops).map(([k,v])=>`<option value="${k}" ${k===f.previous?'selected':''}>${v.name}</option>`).join('')}</select></label><label class="form-label">Default irrigation (mm / season)<input name="irrigation" type="number" min="0" max="1000" required value="${f.irrigation}"></label></div><p class="small muted">Stored in this browser. Opening this field requests regional NASA weather using these coordinates. Global weather is available; crop rules remain an illustrative Indian seasonal template.</p><p class="form-error" id="form-error" role="alert"></p><button class="primary full" type="submit">${field?'Save field changes':'Create field profile'} ${icon('arrow')}</button></form>`}
function snapshotComparison(c){
 const selected=c.state.plans.filter(p=>(c.state.comparePlanIds||[]).includes(p.id));
 if(selected.length!==2)return heading('SAVED SNAPSHOTS','Choose two plans to compare.')+'<a class="primary" href="#plans">Choose saved plans →</a>';
 return heading('SAVED SNAPSHOTS','The same question. Two planning contexts.','Compare recorded inputs and outcomes without changing either saved plan.','<a class="secondary" href="#plans">Back to saved plans</a>')+`<div class="snapshot-columns">${selected.map(p=>`<article class="panel"><div class="eyebrow">MODEL ${esc(p.modelVersion)} · ${p.settings.year}–${p.settings.year+1}</div><h2>${esc(p.name)}</h2><dl class="metadata"><div><dt>Field / area</dt><dd>${esc(p.field.name)} / ${num(p.field.area,1)} ha</dd></div><div><dt>Coordinates / soil</dt><dd>${p.field.lat}°, ${p.field.lon}° / ${p.field.soil}</dd></div><div><dt>Priority</dt><dd>${p.settings.priority}</dd></div>${p.result.weather.map((w,i)=>`<div><dt>Season ${i+1}</dt><dd>${w.window.label}<br>${i?p.settings.secondRainChange:p.settings.rainChange}% rain · +${i?p.settings.secondHeatChange:p.settings.heatChange}°C · ${i?p.settings.secondIrrigation:p.settings.firstIrrigation} mm irrigation</dd></div>`).join('')}</dl><div class="table-scroll"><table><thead><tr><th>Rotation</th><th>Score</th><th>Gap (mm)</th></tr></thead><tbody>${p.result.ranked.map(r=>`<tr><td>${rotationName(r)}</td><td>${r.score??'Excluded'}</td><td>${r.eligible?num(r.gap):'—'}</td></tr>`).join('')}</tbody></table></div><a class="inline-link" href="#plan/${encodeURIComponent(p.id)}">Inspect full snapshot ↗</a></article>`).join('')}</div><div class="honesty-banner">${icon('evidence')}<span>Each snapshot uses its own field, weather, calendar and priority weights. A score difference does not establish measured performance, yield or water savings.</span></div>`;
}
export function renderView(c){let html=({home,dashboard,fields,planner,compare,evidence,plans,plan:report,snapshots:snapshotComparison}[c.route]||home)(c);if(c.route==='plans'){const count=c.state.plans.filter(p=>(c.state.comparePlanIds||[]).includes(p.id)).length;html=`<div class="snapshot-toolbar"><span>${count} / 2 snapshots selected</span>${count===2?'<a class="secondary" href="#snapshots">Compare selected snapshots →</a>':'<span class="small muted">Choose two saved plans below to compare contexts.</span>'}</div>`+html}return html}
